        this.client = client;
    }

    @Override
    protected Result check() {
        MDCUtils.put("healthCheck", "Outbound"); // tag the logs with health check
        Logger.debug("Starting Outbound healthcheck");
        API api = new API(client, null);

        try {
            Response response = api.status();
