            final String message = String.format("Unable to reach: %s, error: %s", api.getWireHost(), e.getMessage());
            Logger.exception(message, e);
            return Result.unhealthy(message);
        } finally {
            Logger.debug("Finished Outbound healthcheck");
        }
    }
}

